/* FCAP Jr R35 | parsing and normalization, no network access */
export const LIMIT_ROWS=10000, MAX_FILE_BYTES=20*1024*1024;
export const FIELDS=[
 ['company_name','Empresa / oportunidade','Nome da empresa, negócio ou lead'],
 ['contact_name','Contato','Pessoa responsável / contato'],
 ['email','E-mail','E-mail do lead'],
 ['phone','Telefone / WhatsApp','DDD e número'],
 ['stage','Etapa do funil','Será associada às etapas FCAP Jr.'],
 ['estimated_value','Valor estimado (R$)','Valor de negócio, não faturamento'],
 ['assigned_to','Responsável no CRM antigo','Mapeado a um usuário FCAP Jr.'],
 ['priority','Prioridade','Alta, média, baixa'],
 ['temperature','Temperatura','Quente, morno, frio'],
 ['segment','Setor / segmento','Área de atuação'],
 ['role_title','Cargo do contato','Cargo ou função'],
 ['need','Necessidade','Problema que o cliente quer resolver'],
 ['source','Origem','Canal ou origem do lead'],
 ['notes','Observações','Histórico ou notas em texto'],
 ['website_url','Site','Link do site'],
 ['instagram_url','Instagram','Perfil ou URL'],
 ['linkedin_url','LinkedIn','Perfil ou URL'],
 ['tiktok_url','TikTok','Perfil ou URL']
];
const FIELD_ALIASES={
 company_name:['empresa','nome empresa','nome da empresa','razao social','nome fantasia','company','company name','organization','organization name','organisation','organisation name','account name','negocio','nome negocio','negocio titulo','titulo negocio','deal title','deal name','deal','oportunidade','titulo da oportunidade','opportunity name','opportunity','lead name','nome lead','titulo lead','title','nome'],
 contact_name:['nome contato','contato','nome completo','pessoa','nome pessoa','responsavel contato','contact name','contact person','person','person name','customer name','full name','first name','firstname','contact','nome cliente','cliente'],
 email:['email','e mail','e-mail','email address','work email','contact email','person email','primary email','email principal','correo electronico'],
 phone:['telefone','celular','whatsapp','numero telefone','telefone contato','phone','phone number','mobile','mobile phone','contact phone','telephone','work phone','numero'],
 stage:['etapa','fase','estagio','situacao','status negocio','etapa negocio','pipeline stage','deal stage','stage','status','funil','sales stage','etapa do funil'],
 estimated_value:['valor','valor negocio','valor da oportunidade','valor estimado','valor previsto','value','deal value','amount','opportunity amount','estimated value','total amount','receita prevista','price','deal amount'],
 assigned_to:['responsavel','vendedor','proprietario','proprietario lead','owner','deal owner','lead owner','assigned to','user responsible','responsavel pelo negocio','usuario responsavel','responsible user'],
 priority:['prioridade','priority','importance','urgencia'],
 temperature:['temperatura','temperature','lead temperature','classificacao','rating'],
 segment:['segmento','setor','ramo','ramo atividade','industry','sector','business sector','industry type','categoria'],
 role_title:['cargo','profissao','funcao','job title','job position','position','role','contact position'],
 need:['necessidade','interesse','demanda','dor','need','needs','interested in','problema'],
 source:['origem','fonte','canal','canal origem','lead source','source','source name','origem do lead','acquisition source'],
 notes:['observacoes','observacao','nota','notas','anotacoes','descricao','comentarios','detalhes','notes','note','description','comments','remarks','mensagem','message'],
 website_url:['site','site web','website','website url','url site','homepage','pagina web'],
 instagram_url:['instagram','instagram url','perfil instagram','ig'],
 linkedin_url:['linkedin','linkedin url','perfil linkedin'],
 tiktok_url:['tiktok','tiktok url','perfil tiktok']
};
export const normalizeKey=(v)=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
const normVal=(v)=>String(v??'').replace(/[\u0000-\u001f]/g,' ').trim();
export const safeText=(v,max=180)=>normVal(v).slice(0,max);
export function detectHeaderMap(headers){const map={};const used=new Set();for(const [field] of FIELDS){let best=-1;let score=0;for(let i=0;i<headers.length;i++){if(used.has(i))continue;const h=normalizeKey(headers[i]);if(!h)continue;if(field==='contact_name'&&/(email|telefone|celular|phone|mobile)/.test(h))continue;const aliases=FIELD_ALIASES[field]||[];let sc=aliases.includes(h)?100:aliases.some(a=>a.length>=6&&(h.startsWith(a+' ')||h.endsWith(' '+a)))?60:0;if(field==='company_name'&&/(empresa|company|organization|organisation|account)/.test(h))sc+=35;if(sc>score){score=sc;best=i}}if(best>=0&&score){map[field]=String(best);used.add(best)}}return map}
export function parseDelimited(text,delimiter=','){const table=[];let row=[],item='',quoted=false;const src=String(text??'').replace(/^\uFEFF/,'');for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){item+='"';i++}else if(!item.length||quoted)quoted=!quoted;else item+='"'}else if(c===delimiter&&!quoted){row.push(item);item=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&src[i+1]==='\n')i++;row.push(item);if(row.some(v=>v.trim()!==''))table.push(row);row=[];item='';if(table.length>LIMIT_ROWS+10)throw Error('Arquivo contém mais de 10.000 linhas. Divida a exportação em partes.')}else item+=c}if(quoted)throw Error('CSV contém aspas não fechadas.');row.push(item);if(row.some(v=>v.trim()!==''))table.push(row);return table}
export function detectDelimiter(text){const sample=String(text).split(/\r?\n/).slice(0,7).join('\n');let best=',',score=-1;for(const delim of [';',',','\t','|']){try{let rows=parseDelimited(sample,delim).slice(0,5);let widths=rows.map(r=>r.length).filter(n=>n>1);if(!widths.length)continue;const n=widths[0],equal=widths.filter(x=>x===n).length;const points=equal*6+n;if(points>score){score=points;best=delim}}catch{}}return best}
export function matrixDataset(matrix,label='Planilha'){const rows=matrix.filter(r=>Array.isArray(r)&&r.some(v=>String(v??'').trim()));if(!rows.length)throw Error('A aba selecionada está vazia.');if(rows.length>LIMIT_ROWS+1)throw Error('Limite de 10.000 registros por importação. Exporte em partes.');const headers=rows[0].map((h,i)=>safeText(h,130)||`Coluna ${i+1}`);const data=rows.slice(1).map(row=>headers.map((_,i)=>safeText(row[i],4000)));return {label,headers,rows:data}}
export function arrayDataset(array,label='JSON'){if(!Array.isArray(array)||!array.length)throw Error('Arquivo sem registros para importar.');if(array.length>LIMIT_ROWS)throw Error('Mais de 10.000 registros. Separe a exportação.');let records=array.filter(x=>x&&typeof x==='object'&&!Array.isArray(x));if(!records.length)throw Error('JSON não contém objetos de leads/contatos.');const flatten=(v,prefix='',out={},depth=0)=>{if(depth>3)return out;for(const [k,val] of Object.entries(v)){const name=(prefix?prefix+' '+k:k).slice(0,150);if(val&&typeof val==='object'&&!Array.isArray(val))flatten(val,name,out,depth+1);else if(Array.isArray(val))out[name]=val.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join('; ').slice(0,4000);else out[name]=safeText(val,4000)}return out};records=records.map(x=>flatten(x));const headers=[...new Set(records.flatMap(Object.keys))].slice(0,150);return{label,headers,rows:records.map(x=>headers.map(h=>safeText(x[h],4000)))}}
export function jsonDatasets(payload){if(Array.isArray(payload))return[arrayDataset(payload,'Registros JSON')];if(!payload||typeof payload!=='object')throw Error('JSON precisa conter uma lista de registros.');const candidates=[['data',payload.data],['results',payload.results],['records',payload.records],['leads',payload.leads],['deals',payload.deals],['contacts',payload.contacts],['companies',payload.companies],['items',payload.items],['oportunidades',payload.oportunidades]];const sets=[];for(const [key,value] of candidates){if(Array.isArray(value)&&value.length&&typeof value[0]==='object')sets.push(arrayDataset(value,key));else if(value&&typeof value==='object'&&Array.isArray(value.items))sets.push(arrayDataset(value.items,key+' / items'))}if(sets.length)return sets;for(const [key,value] of Object.entries(payload)){if(Array.isArray(value)&&value[0]&&typeof value[0]==='object')sets.push(arrayDataset(value,key))}if(!sets.length)throw Error('JSON sem lista reconhecível. Selecione um export de leads, negócios ou contatos.');return sets.slice(0,12)}
function unfoldVcard(str){return String(str).replace(/\r?\n[ \t]/g,'')}
export function vcardDataset(text){const cards=unfoldVcard(text).split(/BEGIN:VCARD/i).slice(1);const items=[];for(const block of cards){let full=block.split(/END:VCARD/i)[0];const entry={};for(const raw of full.split(/\r?\n/)){const k=raw.indexOf(':');if(k<0)continue;const type=raw.slice(0,k).split(';')[0].toUpperCase();let val=raw.slice(k+1).replace(/\\n/gi,' ').replace(/\\,/g,',').trim();if(type==='FN')entry['Nome completo']=val;else if(type==='N'&&!entry['Nome completo'])entry['Nome completo']=val.split(';').filter(Boolean).reverse().join(' ');else if(type==='ORG')entry['Empresa']=val.replace(/;/g,' ');else if(type==='EMAIL'&&!entry['Email'])entry['Email']=val;else if(type==='TEL'&&!entry['Telefone'])entry['Telefone']=val;else if(type==='TITLE')entry['Cargo']=val;else if(type==='NOTE')entry['Observações']=val;else if(type==='URL')entry['Site']=val}if(Object.keys(entry).length)items.push(entry)}if(!items.length)throw Error('Nenhum contato vCard encontrado.');return arrayDataset(items,'Contatos vCard')}
export function xmlDatasets(xmlText,parseXML){const doc=parseXML(xmlText);if(doc.getElementsByTagName('parsererror').length)throw Error('XML malformado.');const candidateTags=['record','row','lead','deal','contact','company','item','oportunidade','negocio','cliente'];const sets=[],allNodes=Array.from(doc.getElementsByTagName('*'));for(const tag of candidateTags){const nodes=allNodes.filter(el=>normalizeKey(el.tagName)===tag);if(nodes.length<1)continue;const records=nodes.slice(0,LIMIT_ROWS+1).map(el=>{const out={};for(const at of Array.from(el.attributes||[]))out[at.name]=at.value;for(const child of Array.from(el.children||[])){if(child.children.length===0)out[child.tagName]=child.textContent||''}return out});sets.push(arrayDataset(records,tag));if(sets.length>=6)break}if(!sets.length)throw Error('XML não contém elementos repetidos de leads, contatos ou negócios.');return sets}
export function numberBR(v){const raw=String(v??'').trim();if(!raw)return 0;const cleaned=raw.replace(/[^\d.,\-]/g,'');let s=cleaned;if(s.includes(',')&&s.includes('.'))s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');else if(s.includes(','))s=s.replace(',','.');else if(/^\d{1,3}(\.\d{3})+(?!\d)/.test(s))s=s.replace(/\./g,'');const n=Number(s);return Number.isFinite(n)&&n>=0&&n<1e12?Math.round(n*100)/100:NaN}
export function normalizedPhone(s){const digits=String(s??'').replace(/\D/g,'');return digits.length>11&&digits.startsWith('55')?digits.slice(2):digits}
export function dedupKey(v){const company=normalizeKey(v.company_name);const email=safeText(v.email).toLowerCase();const phone=normalizedPhone(v.phone);const stage=v.stage_id||'';const contact=normalizeKey(v.contact_name);const amount=String(v.estimated_value??0);return [company,contact,email||'none',phone||'none',stage,amount].join('|')}
export function normalizePriority(v){const s=normalizeKey(v);if(/alto|alta|high|urgent|urgente/.test(s))return'alta';if(/baixo|baixa|low/.test(s))return'baixa';return'media'}
export function normalizeTemperature(v){const s=normalizeKey(v);if(/quente|hot|warm lead/.test(s))return'quente';if(/frio|cold/.test(s))return'frio';return'morno'}
export function suggestStage(value,stages){const n=normalizeKey(value);if(!n)return'';const same=stages.find(x=>normalizeKey(x.name)===n);if(same)return same.id;const aliases=[[/^(new|novo|novo lead|new lead|entrada|lead novo)/,/(novo|new|entrada)/],[/contato|contact|qualifica|prospect/,/contato|qualifica|prospect/],[/diagnostic|agenda|meeting|reuniao/,/diagnostico|agenda|reuniao/],[/proposal|proposta|quote|orcamento/,/proposta|orcamento/],[/negoci|negotiat/,/negoci/],[/won|ganh|fechad|concluid/,/ganh|fechad|concluid/],[/lost|perdid|cancelad/,/perdid|cancelad/]];for(const [origin,target] of aliases){if(origin.test(n)){const t=stages.find(x=>target.test(normalizeKey(x.name)));if(t)return t.id}}return''}
export function likelyDatasets(sets){return sets.map(x=>({...x,quality:Object.keys(detectHeaderMap(x.headers)).length})).sort((a,b)=>b.quality-a.quality)}
